import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { LayaAnswer, LayaDecision, LayaServer, LayaStats } from '../types'
import {
  DEFAULT_CHECKPOINT,
  EXPAND,
  MAX_AREAS,
  ROOT_AREA,
  SAFETY,
  TASK,
  TOOL_DESCRIPTION,
  TOOL_SCHEMA,
  areaQuestion,
  isVisible,
  serverArgv,
  serverEnv,
  top,
  trimAnswers,
  uvxCandidates,
  type Questions,
} from './laya'

const PANE = 'laya'
const TOOL = 'mcp__laya__decide'
const USER_ORIGINS = new Set(['composer', 'bridge', 'sdk'])
const AREA_TTL_MS = 60_000
const HEALTH_EVERY_MS = 20_000

const server = atom({ plugin: 'laya', key: 'server' } as const, { phase: 'checking' } as LayaServer)
const recent = atom({ plugin: 'laya', key: 'recent' } as const, [] as LayaDecision[])
const stats = atom({ plugin: 'laya', key: 'stats' } as const, { checked: 0, flagged: 0, tools: 0 } as LayaStats)
const bandHidden = atom({ plugin: 'laya', key: 'bandHidden' } as const, false)

type Guard = 'show' | 'warn' | 'block' | 'off'
type Options = {
  guard: Guard
  guardThreshold: number
  hints: boolean
  hintThreshold: number
  port: number
  checkpoint: string
}

// Module state: a hot reload starts it over, the host's $.state survives.
let opt: Options = readOptions({})
let starting: Promise<void> | null = null
let childRunning = false
let areaCache: { at: number; areas: Record<string, string> } | null = null
let seq = 0

function readOptions(raw: Readonly<Record<string, unknown>>): Options {
  const num = (v: unknown, fallback: number, lo: number, hi: number) =>
    typeof v === 'number' && Number.isFinite(v) ? Math.min(hi, Math.max(lo, v)) : fallback
  const guard = ['show', 'warn', 'block', 'off'].includes(raw.guard as string) ? (raw.guard as Guard) : 'show'
  return {
    guard,
    guardThreshold: num(raw.guardThreshold, 0.6, 0.05, 1),
    hints: raw.hints !== false,
    hintThreshold: num(raw.hintThreshold, 0.7, 0.05, 1),
    port: Math.round(num(raw.port, 8741, 1024, 65535)),
    checkpoint: typeof raw.checkpoint === 'string' ? raw.checkpoint.trim() : DEFAULT_CHECKPOINT,
  }
}

const p2 = (x: number) => x.toFixed(2)
const human = (s: string) => s.replace(/_/g, ' ')
const oneLine = (s: string) => s.replace(/\s+/g, ' ').trim()
const pad = (n: number) => String(n).padStart(2, '0')
const clock = (ts: number) => {
  const d = new Date(ts)
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`
}
const preview = (state: unknown) => {
  if (typeof state === 'string') return state
  const values = state && typeof state === 'object' ? Object.values(state) : []
  return values.length === 1 && typeof values[0] === 'string' ? values[0] : JSON.stringify(state)
}
const base = () => `http://127.0.0.1:${opt.port}`

/** "billing 0.97" for a choice, "yes 0.18" for a yes/no, "urgent 1.86" for a scale. */
function answerText(a: LayaAnswer): string {
  if (a.type === 'choice') {
    const t = top(a)
    return t ? `${human(t.label)} ${p2(t.p)}` : '?'
  }
  if (a.type === 'noul') return `yes ${p2(a.noul ?? 0)}`
  const level = a.legend ? a.legend[String(Math.round(a.score ?? 0))] : undefined
  return `${level ? level.split(':')[0] : 'score'} ${p2(a.score ?? 0)}`
}

function hintFor(answers: Record<string, LayaAnswer>, text: string): string | undefined {
  if (text.length < 15) return undefined
  const parts: string[] = []
  const area = top(answers.area)
  const task = top(answers.task)
  if (area && area.p >= opt.hintThreshold) {
    parts.push(
      area.label === ROOT_AREA
        ? `is about the files in the project root (p=${p2(area.p)})`
        : `is about the \`${area.label}/\` folder (p=${p2(area.p)})`,
    )
  }
  if (task && task.p >= opt.hintThreshold) parts.push(`is a ${human(task.label)} task (p=${p2(task.p)})`)
  if (parts.length === 0) return undefined
  return `Laya, a small local classifier, guesses this prompt ${parts.join(' and ')}. Treat it as a hint and verify before relying on it.`
}

/* ---------------- the local Laya server ---------------- */

async function health($: EngineInterface): Promise<{ device?: string } | null> {
  try {
    const res = await $.http.fetch(`${base()}/health`)
    if (!res.ok) return null
    const body = JSON.parse(res.text) as { status?: string; device?: string }
    if (body.status !== 'ok') return null
    // laya-serve reports its setting, and "auto" names no device.
    return { device: body.device && body.device !== 'auto' ? body.device : undefined }
  } catch {
    return null
  }
}

/** One forward pass; rejects on a non-200 answer or after `timeoutMs`. */
async function predict(
  $: EngineInterface,
  state: unknown,
  questions: Questions,
  timeoutMs: number,
): Promise<{ answers: Record<string, LayaAnswer>; model?: string }> {
  const stop = new AbortController()
  const timeout = $.clock.sleep(timeoutMs, { signal: stop.signal }).then(
    () => Promise.reject(new Error(`Laya did not answer within ${timeoutMs} ms`)),
    () => new Promise<never>(() => {}),
  )
  const call = $.http
    .fetch(`${base()}/v1/systemone`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ state, questions }),
    })
    .then(res => {
      if (!res.ok) throw new Error(`Laya answered HTTP ${res.status}: ${res.text.slice(0, 200)}`)
      const body = JSON.parse(res.text) as { answers: Record<string, LayaAnswer>; routing?: { model?: string } }
      return { answers: trimAnswers(body.answers), model: body.routing?.model }
    })
  try {
    return await Promise.race([call, timeout])
  } finally {
    stop.abort()
  }
}

/** uv's `uvx`: on PATH, or where the uv installers put it. */
async function findUvx($: EngineInterface): Promise<string | null> {
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE')) ?? ''
  for (const candidate of uvxCandidates(home)) {
    try {
      const { exitCode } = await $.process.run([candidate, '--version'], { timeoutMs: 10_000 })
      if (exitCode === 0) return candidate
    } catch {
      // not there; try the next
    }
  }
  return null
}

async function setServer($: EngineInterface, next: LayaServer) {
  await update($, server, () => next)
}

/** Runs `laya-serve` for this session's life; other sessions reuse it. */
async function runServer($: EngineInterface, uvx: string) {
  childRunning = true
  let reason = 'the Laya server stopped'
  try {
    const child = $.process.spawn({ argv: serverArgv(uvx, $.plugin.root), env: serverEnv(opt.port, opt.checkpoint) })
    for await (const piece of child) {
      for (const raw of piece.text.split(/\r?\n/)) {
        const line = raw.trim()
        if (!line) continue
        $.ui.log(`laya-serve: ${line}`, { to: 'debug' })
        if (/Uvicorn running|Application startup complete/.test(line)) {
          const up = await health($)
          if (up && (await read($, server)).phase !== 'ready') {
            await setServer($, { phase: 'ready', device: up.device })
            $.ui.toast(`Laya is ready on ${up.device ?? 'this machine'}`)
          }
        } else if (/address already in use|Errno 48|Errno 98|10048/.test(line)) {
          reason = `port ${opt.port} is taken by another program`
        } else if (/Installed \d+ package|Started server process/.test(line)) {
          await setServer($, { phase: 'loading', detail: 'loading the model (downloads ~800 MB on first run)' })
        } else if (/^(Downloading|Downloaded|Prepared|Resolved|Building|Built)/.test(line)) {
          await setServer($, { phase: 'installing', detail: line.slice(0, 70) })
        }
      }
    }
  } catch (err) {
    reason = err instanceof Error ? err.message : String(err)
  }
  childRunning = false
  const up = await health($)
  await setServer($, up ? { phase: 'ready', device: up.device } : { phase: 'offline', detail: reason })
  await refreshStatus($)
}

async function startIfNeeded($: EngineInterface) {
  const up = await health($)
  if (up) {
    await setServer($, { phase: 'ready', device: up.device })
    return
  }
  if (childRunning) return
  const uvx = await findUvx($)
  if (!uvx) {
    await setServer($, { phase: 'missing-uv', detail: 'install uv (docs.astral.sh/uv), then restart Claude Code' })
    return
  }
  await setServer($, { phase: 'installing', detail: 'preparing Laya (first run downloads ~1 GB)' })
  void runServer($, uvx)
}

function ensureServer($: EngineInterface): Promise<void> {
  if (!starting) {
    starting = startIfNeeded($).finally(() => {
      starting = null
    })
  }
  return starting
}

async function tick($: EngineInterface) {
  const srv = await read($, server)
  if (srv.phase === 'missing-uv' || childRunning) return
  const up = await health($)
  if (up && srv.phase !== 'ready') await setServer($, { phase: 'ready', device: up.device })
  if (!up) await ensureServer($)
}

/* ---------------- project folders as Laya options ---------------- */

async function childNames($: EngineInterface, path: string, limit: number): Promise<string[]> {
  try {
    return (await $.fs.list(path)).filter(e => isVisible(e.name)).slice(0, limit).map(e => e.name)
  } catch {
    return []
  }
}

async function subfolders($: EngineInterface, path: string): Promise<string[]> {
  try {
    return (await $.fs.list(path)).filter(e => e.kind === 'dir' && isVisible(e.name)).map(e => e.name)
  } catch {
    return []
  }
}

/**
 * The project's folders as choice options, `name -> "folder name: a, b, c"`. A lone
 * source folder (src, packages, ...) opens one level so the guess stays useful;
 * files at the root are one option of their own.
 */
async function projectAreas($: EngineInterface): Promise<Record<string, string>> {
  const root = await $.session.cwd()
  let entries: { name: string; kind: string }[]
  try {
    entries = await $.fs.list(root)
  } catch {
    return {}
  }
  const dirs = entries.filter(e => e.kind === 'dir' && isVisible(e.name)).map(e => e.name)
  const files = entries.filter(e => e.kind === 'file' && isVisible(e.name)).map(e => e.name)
  const openUp = dirs.some(d => EXPAND.has(d)) && dirs.length <= 4
  const areas: Record<string, string> = {}
  const full = () => Object.keys(areas).length >= MAX_AREAS - 1

  for (const dir of dirs) {
    if (full()) break
    if (openUp && EXPAND.has(dir)) {
      for (const sub of await subfolders($, `${root}/${dir}`)) {
        if (full()) break
        areas[`${dir}/${sub}`] = `folder ${dir}/${sub}: ${(await childNames($, `${root}/${dir}/${sub}`, 6)).join(', ')}`
      }
    }
    if (!full()) areas[dir] = `folder ${dir}: ${(await childNames($, `${root}/${dir}`, 6)).join(', ')}`
  }
  if (files.length > 0) areas[ROOT_AREA] = `files in the project root: ${files.slice(0, 8).join(', ')}`
  return areas
}

async function cachedAreas($: EngineInterface) {
  const now = await $.clock.now()
  if (!areaCache || now - areaCache.at > AREA_TTL_MS) areaCache = { at: now, areas: await projectAreas($) }
  return areaCache.areas
}

/* ---------------- decisions and the status line ---------------- */

async function refreshStatus($: EngineInterface) {
  if (!(await read($, bandHidden))) {
    $.ui.status(undefined)
    return
  }
  const s = await read($, stats)
  const srv = await read($, server)
  $.ui.status(srv.phase === 'ready' ? `Laya ✓ ${s.checked} checked · ${s.flagged} flagged` : `Laya: ${srv.phase}`)
}

async function record($: EngineInterface, d: Omit<LayaDecision, 'id'>) {
  const decision: LayaDecision = { ...d, id: `${d.ts}-${++seq}` }
  await update($, recent, list => [...list, decision].slice(-50))
  await update($, stats, s => ({
    checked: s.checked + (d.source === 'prompt' ? 1 : 0),
    flagged: s.flagged + (d.action && d.action !== 'allowed' ? 1 : 0),
    tools: s.tools + (d.source === 'tool' ? 1 : 0),
  }))
  await refreshStatus($)
}

async function setHidden($: EngineInterface, hidden: boolean) {
  await update($, bandHidden, () => hidden)
  await $.store.set('bandHidden', hidden)
  await refreshStatus($)
}

async function clearDecisions($: EngineInterface) {
  await update($, recent, () => [])
  await update($, stats, () => ({ checked: 0, flagged: 0, tools: 0 }))
  await refreshStatus($)
}

async function openPane($: EngineInterface) {
  return $.ui.open({ id: PANE, title: 'Laya decisions' })
}

async function closePane($: EngineInterface) {
  await $.ui.close({ id: PANE })
}

/* ---------------- hooks ---------------- */

export const register: Register = (on, options) => {
  opt = readOptions(options)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'laya',
      description: 'Laya: open the decisions pane; "/laya hide" or "/laya show" toggles the band',
      argumentHint: '[hide|show]',
    })
    await $.tool.register({ name: 'decide', description: TOOL_DESCRIPTION, inputSchema: TOOL_SCHEMA })
    const stored = await $.store.get('bandHidden')
    if (typeof stored === 'boolean') await update($, bandHidden, () => stored)
    void ensureServer($)
    $.clock.every(HEALTH_EVERY_MS, () => {
      void tick($)
    })
    return next(e)
  })

  // Every prompt you send: one Laya pass answers safety, task type and folder.
  on('prompt.submit', async ($, e, next) => {
    const text = e.text.trim()
    const wantsGuard = opt.guard !== 'off'
    if (!USER_ORIGINS.has(e.origin.kind) || !text || (!wantsGuard && !opt.hints)) return next(e)
    if ((await read($, server)).phase !== 'ready') {
      void ensureServer($)
      return next(e)
    }

    const questions: Questions = {}
    if (wantsGuard) questions.safety = SAFETY
    if (opt.hints) {
      questions.task = TASK
      const areas = await cachedAreas($)
      if (Object.keys(areas).length >= 2) questions.area = areaQuestion(areas)
    }

    const startedAt = await $.clock.now()
    let answers: Record<string, LayaAnswer>
    try {
      ;({ answers } = await predict($, { prompt: text }, questions, 4_000))
    } catch (err) {
      $.ui.log(`laya: prompt not checked: ${err instanceof Error ? err.message : String(err)}`, { to: 'debug' })
      void tick($)
      return next(e)
    }
    const latencyMs = (await $.clock.now()) - startedAt

    const risk = wantsGuard ? 1 - (answers.safety?.probabilities?.genuine_task ?? 1) : undefined
    const flagged = risk !== undefined && risk >= opt.guardThreshold
    const action = !wantsGuard
      ? undefined
      : !flagged
        ? 'allowed'
        : opt.guard === 'block'
          ? 'blocked'
          : opt.guard === 'warn'
            ? 'warned'
            : 'noted'
    const hint = opt.hints ? hintFor(answers, text) : undefined
    await record($, { ts: startedAt, source: 'prompt', text, answers, latencyMs, risk, action, hint })

    if (action === 'blocked') {
      $.ui.toast(`Laya blocked this prompt (attack score ${p2(risk ?? 0)})`)
      return {
        drop: `Laya blocked this prompt: attack score ${p2(risk ?? 0)} is at or above ${p2(opt.guardThreshold)}. Rephrase it, or set Laya's safety check to "show" in /config.`,
      }
    }
    if (action === 'warned') $.ui.toast(`Laya: this prompt looks like an attack (${p2(risk ?? 0)}). Sent anyway.`)
    return hint ? next({ ...e, context: [...(e.context ?? []), hint] }) : next(e)
  })

  // The tool Claude calls: mcp__laya__decide.
  on('tool.call', { tool: TOOL }, async ($, e) => {
    const { state, questions } = e as unknown as { state?: unknown; questions?: Questions }
    if (state === undefined || !questions || typeof questions !== 'object' || Object.keys(questions).length === 0) {
      return { deny: 'laya decide needs `state` and at least one question in `questions`.' }
    }
    const srv = await read($, server)
    if (srv.phase !== 'ready') {
      void ensureServer($)
      return {
        deny: `The local Laya model is not ready (${srv.phase}${srv.detail ? `: ${srv.detail}` : ''}). Try again in about 30 seconds, or continue without it.`,
      }
    }
    const startedAt = await $.clock.now()
    try {
      const { answers, model } = await predict($, state, questions, 15_000)
      const latencyMs = (await $.clock.now()) - startedAt
      await record($, { ts: startedAt, source: 'tool', text: preview(state), answers, latencyMs })
      return { result: JSON.stringify({ answers, latency_ms: Math.round(latencyMs), model }, null, 1) }
    } catch (err) {
      return { deny: `Laya could not answer: ${err instanceof Error ? err.message : String(err)}` }
    }
  })

  on('command.run', { command: 'laya' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'hide' || arg === 'show') {
      await setHidden($, arg === 'hide')
      return { text: arg === 'hide' ? 'Laya band hidden; "/laya show" brings it back.' : 'Laya band shown.' }
    }
    const opened = await openPane($)
    return { text: opened.isPlaced ? 'Opened the Laya decisions pane.' : 'The Laya pane needs a wider window.' }
  })

  // The one-line band above the prompt.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, bandHidden))) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const srv = await read($, server)
    const list = await read($, recent)
    const s = await read($, stats)
    const last = list[list.length - 1]
    const wide = e.props.bodyColumns >= 100

    let icon: { glyph: string; color: string }
    let detail: string
    if (srv.phase !== 'ready') {
      const phases: Record<string, { glyph: string; color: string }> = {
        checking: { glyph: '◌ starting', color: 'yellow' },
        installing: { glyph: '◌ installing', color: 'yellow' },
        loading: { glyph: '◌ loading', color: 'yellow' },
        offline: { glyph: '✕ offline', color: 'red' },
        'missing-uv': { glyph: '✕ needs uv', color: 'red' },
      }
      icon = phases[srv.phase] ?? { glyph: '◌ starting', color: 'yellow' }
      detail = srv.detail ?? ''
    } else if (!last) {
      icon = { glyph: '● ready', color: 'green' }
      detail = `on ${srv.device ?? 'this machine'} · safety ${opt.guard} · hints ${opt.hints ? 'on' : 'off'}`
    } else if (last.source === 'tool') {
      icon = { glyph: '⚙ Claude asked', color: 'magenta' }
      detail = `${Object.entries(last.answers).map(([n, a]) => `${human(n)}: ${answerText(a)}`).join(' · ')} · ${Math.round(last.latencyMs)} ms`
    } else {
      icon = last.action === 'blocked'
        ? { glyph: '⛔ blocked', color: 'red' }
        : last.action && last.action !== 'allowed'
          ? { glyph: '! attack?', color: 'yellow' }
          : { glyph: last.action ? '✓ safe' : '✓ checked', color: 'green' }
      const bits: string[] = []
      if (last.risk !== undefined) bits.push(`attack ${p2(last.risk)}`)
      const area = top(last.answers.area)
      const task = top(last.answers.task)
      if (area) bits.push(`${area.label === ROOT_AREA ? 'root files' : `${area.label}/`} ${p2(area.p)}`)
      if (task) bits.push(`${human(task.label)} ${p2(task.p)}`)
      bits.push(`${Math.round(last.latencyMs)} ms`)
      if (last.hint) bits.push('hint sent')
      detail = bits.join(' · ')
    }

    return (
      <Box flexDirection="row" gap={1}>
        <Text bold color="cyan">◆ Laya</Text>
        <Text bold color={icon.color}>{icon.glyph}</Text>
        <Box flexGrow={1} flexShrink={1}>
          <Text dimColor wrap="truncate-end">{detail}</Text>
        </Box>
        {wide ? <Text dimColor>{`${s.checked} checked · ${s.flagged} flagged · ${s.tools} calls`}</Text> : null}
        <Button key="laya-details" label="details" plain onPress={() => void openPane($)} />
        <Button key="laya-hide" label="hide" plain onPress={() => void setHidden($, true)} />
      </Box>
    )
  })

  // The /laya pane: recent decisions with probability bars.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const srv = await read($, server)
    const list = await read($, recent)
    const s = await read($, stats)
    const hidden = await read($, bandHidden)
    const columns = e.props.bodyColumns || e.viewport?.columns || 80
    const barWidth = Math.max(6, Math.min(20, columns - 46))
    const room = Math.max(8, (e.viewport?.rows ?? 30) - 6)

    const bar = (p: number, color: string, key: string) => {
      const filled = Math.min(barWidth, Math.max(p > 0 ? 1 : 0, Math.round(p * barWidth)))
      return (
        <Box key={key} flexDirection="row">
          <Text color={color}>{'█'.repeat(filled)}</Text>
          <Text dimColor>{'░'.repeat(barWidth - filled)}</Text>
        </Box>
      )
    }

    const answerRow = (d: LayaDecision, name: string, a: LayaAnswer) => {
      let p = 0
      let label = ''
      let color = 'cyan'
      if (name === 'safety' && d.source === 'prompt') {
        p = d.risk ?? 0
        label = `attack ${p2(p)}`
        color = p >= opt.guardThreshold ? 'red' : p >= 0.5 ? 'yellow' : 'green'
      } else if (a.type === 'choice') {
        const probs = Object.entries(a.probabilities ?? {}).sort((x, y) => y[1] - x[1])
        p = probs[0]?.[1] ?? 0
        label = `${human(probs[0]?.[0] ?? '?')} ${p2(p)}${probs[1] ? `  (next: ${human(probs[1][0])} ${p2(probs[1][1])})` : ''}`
      } else if (a.type === 'noul') {
        p = a.noul ?? 0
        label = `yes ${p2(p)}`
      } else {
        const levels = Object.keys(a.legend ?? {}).length || 1
        p = Math.min(1, (a.score ?? 0) / Math.max(1, levels - 1))
        label = answerText(a)
      }
      return (
        <Box key={`${d.id}-${name}`} flexDirection="row" gap={1}>
          <Text>{`  ${human(name).padEnd(9).slice(0, 9)}`}</Text>
          {bar(p, color, `${d.id}-${name}-bar`)}
          <Text wrap="truncate-end">{label}</Text>
        </Box>
      )
    }

    const blocks: JSX.Element[] = []
    let used = 0
    for (const d of [...list].reverse()) {
      const height = 3 + Object.keys(d.answers).length + (d.hint ? 1 : 0)
      if (blocks.length > 0 && used + height > room) break
      used += height
      const badge = d.source === 'tool'
        ? { text: 'Claude tool call', color: 'magenta' }
        : d.action === 'blocked'
          ? { text: 'Prompt · blocked', color: 'red' }
          : d.action && d.action !== 'allowed'
            ? { text: `Prompt · flagged (${d.action})`, color: 'yellow' }
            : { text: 'Prompt · safe', color: 'green' }
      blocks.push(
        <Box key={d.id} flexDirection="column" marginTop={1}>
          <Box flexDirection="row" gap={1}>
            <Text dimColor>{clock(d.ts)}</Text>
            <Text bold color={badge.color}>{badge.text}</Text>
            <Text dimColor>{`${Math.round(d.latencyMs)} ms`}</Text>
          </Box>
          <Text dimColor wrap="truncate-end">{`  “${oneLine(d.text)}”`}</Text>
          {Object.entries(d.answers).map(([name, a]) => answerRow(d, name, a))}
          {d.hint ? <Text color="cyan" wrap="truncate-end">{'  → folder/task hint passed to Claude'}</Text> : null}
        </Box>,
      )
    }

    const status = srv.phase === 'ready'
      ? `● ready on ${srv.device ?? 'this machine'} · port ${opt.port}`
      : `${srv.phase}${srv.detail ? ` · ${srv.detail}` : ''}`
    const statusColor = srv.phase === 'ready' ? 'green' : srv.phase === 'offline' || srv.phase === 'missing-uv' ? 'red' : 'yellow'

    return (
      <Box flexDirection="column">
        <Text color={statusColor} wrap="truncate-end">{status}</Text>
        <Text dimColor wrap="truncate-end">
          {`${s.checked} prompts checked · ${s.flagged} flagged · ${s.tools} Claude tool calls · safety: ${opt.guard} at ${p2(opt.guardThreshold)} · hints: ${opt.hints ? `on at ${p2(opt.hintThreshold)}` : 'off'}`}
        </Text>
        {blocks.length === 0 ? (
          <Box marginTop={1}>
            <Text dimColor>No decisions yet. Send a prompt, or ask Claude to use the laya decide tool.</Text>
          </Box>
        ) : null}
        {blocks}
        <Box flexDirection="row" gap={2} marginTop={1}>
          <Button key="laya-band" label={hidden ? 'show band' : 'hide band'} plain onPress={() => void setHidden($, !hidden)} />
          <Button key="laya-clear" label="clear" plain onPress={() => void clearDecisions($)} />
          <Button key="laya-close" label="close" plain onPress={() => void closePane($)} />
        </Box>
      </Box>
    )
  })
}

