/** One answer as Laya returns it, trimmed to what the plugin shows. */
export type LayaAnswer = {
  type: 'choice' | 'noul' | 'score'
  choice?: string
  probabilities?: Record<string, number>
  noul?: number
  score?: number
  legend?: Record<string, string>
}

/** Where the shared local Laya server stands. */
export type LayaServer = {
  phase: 'checking' | 'installing' | 'loading' | 'ready' | 'offline' | 'missing-uv'
  detail?: string
  device?: string
}

/** One real Laya decision: a prompt check or a call Claude made. */
export type LayaDecision = {
  id: string
  ts: number
  source: 'prompt' | 'tool'
  text: string
  answers: Record<string, LayaAnswer>
  latencyMs: number
  /** Prompt checks only: the attack score and what the guard did with it. */
  risk?: number
  action?: 'allowed' | 'noted' | 'warned' | 'blocked'
  /** Prompt checks only: the hint passed to Claude, when one was confident enough. */
  hint?: string
}

export type LayaStats = { checked: number; flagged: number; tools: number }

declare module 'claude-code' {
  interface PluginState {
    laya: {
      server: LayaServer
      recent: LayaDecision[]
      stats: LayaStats
      bandHidden: boolean
    }
  }
}
